import {PDFArray,PDFDict,PDFRef,PDFDocument,PDFName,PDFRawStream,decodePDFRawStream} from 'pdf-lib';
import {privatePhonePatterns,redactPrivatePhones} from '@legalitt/shared';

/** Privacy projection for PDFs generated by our bundled-font renderers. Remove
 * the actual encoded glyphs, not a rectangle over selectable text. Original
 * objects and historical rows remain unchanged. This deliberately does not OCR
 * identity evidence or modify arbitrary client uploads. */
export async function privateGeneratedPdf(bytes:Uint8Array,phones:unknown[],hideNoticeAge=false):Promise<Uint8Array|null>{
 const patterns=privatePhonePatterns(phones);
 if(hideNoticeAge)patterns.push(/\bAge[d]?\s*:?\s*\d{1,3}(?:\s*years?(?:\s*old)?)?/gi);
 if(!patterns.length)return null;
 const pdf=await PDFDocument.load(bytes);let changed=false;
 for(const page of pdf.getPages()){
  const fontResources=page.node.Resources()?.lookup(PDFName.of('Font'));
  if(!(fontResources instanceof PDFDict))continue;
  const fonts=new Map<string,Map<string,string>>();
  for(const [name,ref]of fontResources.entries()){
   const font=pdf.context.lookup(ref);if(!(font instanceof PDFDict))continue;
   const cmap=font.lookup(PDFName.of('ToUnicode'));if(!(cmap instanceof PDFRawStream))continue;
   const source=Buffer.from(decodePDFRawStream(cmap).decode()).toString(),map=new Map<string,string>();
   for(const block of source.matchAll(/beginbfchar\s+([\s\S]*?)endbfchar/g))for(const [,glyph,text]of block[1].matchAll(/<([\da-f]+)>\s*<([\da-f]+)>/gi))map.set(glyph.toUpperCase(),(text.match(/.{4}/g)??[]).map(v=>String.fromCharCode(parseInt(v,16))).join(''));
   fonts.set(name.toString(),map);
  }
  const contents=page.node.Contents();if(!contents)continue;
  const refs=contents instanceof PDFArray?contents.asArray():[contents];
  const streams=refs.map(ref=>{const raw=pdf.context.lookup(ref);if(!(raw instanceof PDFRawStream))throw Error('Generated PDF has an unsupported content stream.');return {ref,source:Buffer.from(decodePDFRawStream(raw).decode()).toString('latin1')};});
  let text='';const glyphs:{stream:number;start:number;end:number;from:number;to:number}[]=[];
  streams.forEach(({source},stream)=>{
   for(const block of source.matchAll(/\bBT\b([\s\S]*?)\bET\b/g)){
    const font=block[1].match(/(\/[^\s]+)\s+[\d.]+\s+Tf/),map=font&&fonts.get(font[1]);if(!map)continue;
    const bodyStart=block.index!+block[0].indexOf(block[1]);
    for(const shown of block[1].matchAll(/<([\da-f]+)>\s*Tj/gi)){
     const offset=bodyStart+shown.index!+1;
     for(let i=0;i<shown[1].length;i+=4){const value=map.get(shown[1].slice(i,i+4).toUpperCase())??'';glyphs.push({stream,start:offset+i,end:offset+i+4,from:text.length,to:text.length+value.length});text+=value;}
    }
   }
  });
  const ranges=patterns.flatMap(p=>[...text.matchAll(new RegExp(p.source,p.flags))].map(m=>({from:m.index!,to:m.index!+m[0].length})));
  for(const [index,stream]of streams.entries()){
   let source=stream.source;const remove=glyphs.filter(g=>g.stream===index&&ranges.some(r=>g.from<r.to&&g.to>r.from));
   for(const g of remove.reverse())source=source.slice(0,g.start)+source.slice(g.end);
   // ActualText is selectable/accessibility content independent of glyphs.
   source=source.replace(/\/ActualText\s*<([\da-f]+)>/gi,(all,hex:string)=>{const value=(hex.replace(/^FEFF/i,'').match(/.{4}/g)??[]).map(v=>String.fromCharCode(parseInt(v,16))).join('');let safe=redactPrivatePhones(value,phones);if(hideNoticeAge)safe=safe.replace(/\bAge[d]?\s*:?\s*\d{1,3}(?:\s*years?(?:\s*old)?)?/gi,'');if(safe===value)return all;return '/ActualText <FEFF'+[...safe].map(c=>c.charCodeAt(0).toString(16).padStart(4,'0')).join('')+'>';});
   if(source!==stream.source){changed=true;const replacement=pdf.context.flateStream(Buffer.from(source,'latin1'));if(stream.ref instanceof PDFRef)pdf.context.assign(stream.ref,replacement);else throw Error('Generated PDF content is not indirect.');}
  }
 }
 if(!changed)return null;
 if(pdf.getTitle())pdf.setTitle(redactPrivatePhones(pdf.getTitle()!,phones));
 if(pdf.getSubject())pdf.setSubject(redactPrivatePhones(pdf.getSubject()!,phones));
 return pdf.save();
}
